-- Exact chain values are numeric(78,0); the TypeScript boundary treats them as decimal strings.
CREATE TABLE IF NOT EXISTS market_windows (id text PRIMARY KEY, market_id text NOT NULL UNIQUE, pool_address text NOT NULL, pool_nonce numeric(78,0), market_address text, asset text NOT NULL, interval_sec numeric(78,0), trading_start numeric(78,0) NOT NULL, expiry numeric(78,0) NOT NULL, status text NOT NULL, resolution jsonb, created_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS market_windows_pool_nonce_idx ON market_windows(pool_address, pool_nonce);
CREATE INDEX IF NOT EXISTS market_windows_expiry_idx ON market_windows(expiry);
CREATE TABLE IF NOT EXISTS capture_sessions (id text PRIMARY KEY, market_id text NOT NULL, mode text NOT NULL, started_at timestamptz NOT NULL, ended_at timestamptz, sdk_version text NOT NULL, status text NOT NULL, last_event_at timestamptz, last_block numeric(78,0), metadata jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS capture_sessions_market_started_idx ON capture_sessions(market_id, started_at);
CREATE TABLE IF NOT EXISTS capture_gaps (id text PRIMARY KEY, capture_session_id text NOT NULL, market_id text NOT NULL, reason text NOT NULL, from_block numeric(78,0), to_block numeric(78,0), detected_at timestamptz NOT NULL, recovered_at timestamptz, details jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS capture_gaps_session_detected_idx ON capture_gaps(capture_session_id, detected_at);
CREATE TABLE IF NOT EXISTS source_orders (id text PRIMARY KEY, market_id text NOT NULL, capture_session_id text, source_order_id text NOT NULL, pool_address text NOT NULL, owner text, side text, is_bid boolean, price numeric(78,0), full_quantity numeric(78,0), remaining_quantity numeric(78,0), filled_quantity numeric(78,0), status text, placed_at numeric(78,0), block_number numeric(78,0), tx_hash text, source jsonb NOT NULL, UNIQUE(market_id, source_order_id));
CREATE INDEX IF NOT EXISTS source_orders_market_time_idx ON source_orders(market_id, placed_at);
CREATE TABLE IF NOT EXISTS source_fills (id text PRIMARY KEY, market_id text NOT NULL, capture_session_id text, source_fill_id text NOT NULL, pool_address text NOT NULL, price numeric(78,0) NOT NULL, quantity numeric(78,0) NOT NULL, quote_quantity numeric(78,0) NOT NULL, timestamp numeric(78,0) NOT NULL, block_number numeric(78,0) NOT NULL, log_index numeric(78,0) NOT NULL, tx_hash text NOT NULL, source jsonb NOT NULL, UNIQUE(market_id, source_fill_id));
CREATE INDEX IF NOT EXISTS source_fills_market_time_idx ON source_fills(market_id, timestamp);
CREATE INDEX IF NOT EXISTS source_fills_block_log_idx ON source_fills(block_number, log_index);
CREATE TABLE IF NOT EXISTS source_candles (id text PRIMARY KEY, market_id text NOT NULL, pool_address text NOT NULL, interval_sec numeric(78,0) NOT NULL, bucket_start numeric(78,0) NOT NULL, open_price numeric(78,0) NOT NULL, high numeric(78,0) NOT NULL, low numeric(78,0) NOT NULL, close_price numeric(78,0) NOT NULL, base_volume numeric(78,0) NOT NULL, quote_volume numeric(78,0) NOT NULL, trade_count numeric(78,0) NOT NULL, source jsonb NOT NULL, UNIQUE(market_id, interval_sec, bucket_start));
CREATE INDEX IF NOT EXISTS source_candles_market_time_idx ON source_candles(market_id, bucket_start);
CREATE UNIQUE INDEX IF NOT EXISTS replay_datasets_market_hash_uq ON replay_datasets(market_id, integrity_hash);
CREATE INDEX IF NOT EXISTS replay_datasets_market_captured_idx ON replay_datasets(market_id, captured_at);
CREATE TABLE IF NOT EXISTS replay_events (id text PRIMARY KEY, dataset_id text NOT NULL, market_id text NOT NULL, sequence numeric(78,0) NOT NULL, event_timestamp numeric(78,0) NOT NULL, event_kind text NOT NULL, source_record_id text, payload jsonb NOT NULL, UNIQUE(dataset_id, sequence));
CREATE INDEX IF NOT EXISTS replay_events_market_time_idx ON replay_events(market_id, event_timestamp);
CREATE TABLE IF NOT EXISTS strategy_definitions (id text PRIMARY KEY, name text NOT NULL, version text NOT NULL, definition_hash text NOT NULL UNIQUE, language text NOT NULL, source text NOT NULL, parameters jsonb NOT NULL, created_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS strategy_definitions_name_idx ON strategy_definitions(name);
CREATE TABLE IF NOT EXISTS strategy_runs (id text PRIMARY KEY, dataset_id text NOT NULL, market_id text NOT NULL, strategy_definition_id text NOT NULL, started_at timestamptz NOT NULL, completed_at timestamptz, status text NOT NULL, config jsonb NOT NULL, deterministic_seed text NOT NULL, error text);
CREATE INDEX IF NOT EXISTS strategy_runs_dataset_idx ON strategy_runs(dataset_id);
CREATE TABLE IF NOT EXISTS simulated_orders (id text PRIMARY KEY, strategy_run_id text NOT NULL, market_id text NOT NULL, client_order_key text NOT NULL, side text NOT NULL, requested_quantity numeric(78,0) NOT NULL, limit_price numeric(78,0), submitted_at numeric(78,0) NOT NULL, latency_ms numeric(78,0) NOT NULL, status text NOT NULL, assumptions jsonb NOT NULL, UNIQUE(strategy_run_id, client_order_key));
CREATE TABLE IF NOT EXISTS simulated_fills (id text PRIMARY KEY, simulated_order_id text NOT NULL, strategy_run_id text NOT NULL, market_id text NOT NULL, price numeric(78,0) NOT NULL, quantity numeric(78,0) NOT NULL, fee numeric(78,0) NOT NULL, filled_at numeric(78,0) NOT NULL, source_event_id text);
CREATE INDEX IF NOT EXISTS simulated_fills_order_idx ON simulated_fills(simulated_order_id);
CREATE TABLE IF NOT EXISTS run_metrics (id text PRIMARY KEY, strategy_run_id text NOT NULL, metric_key text NOT NULL, metric_value text NOT NULL, unit text, metadata jsonb NOT NULL, UNIQUE(strategy_run_id, metric_key));
CREATE TABLE IF NOT EXISTS shadow_sessions (id text PRIMARY KEY, market_id text NOT NULL, strategy_definition_id text NOT NULL, started_at timestamptz NOT NULL, ended_at timestamptz, status text NOT NULL, capture_session_id text, config jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS shadow_sessions_market_started_idx ON shadow_sessions(market_id, started_at);
CREATE TABLE IF NOT EXISTS shadow_intents (id text PRIMARY KEY, shadow_session_id text NOT NULL, market_id text NOT NULL, sequence numeric(78,0) NOT NULL, observed_at numeric(78,0) NOT NULL, side text NOT NULL, quantity numeric(78,0) NOT NULL, reference_price numeric(78,0), decision jsonb NOT NULL, UNIQUE(shadow_session_id, sequence));
CREATE TABLE IF NOT EXISTS verification_records (id text PRIMARY KEY, market_id text NOT NULL, dataset_id text, strategy_run_id text, kind text NOT NULL, verified_at timestamptz NOT NULL, chain_id numeric(78,0), block_number numeric(78,0), tx_hash text, result text NOT NULL, evidence jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS verification_records_market_time_idx ON verification_records(market_id, verified_at);
CREATE TABLE IF NOT EXISTS optional_run_attestations (id text PRIMARY KEY, strategy_run_id text NOT NULL UNIQUE, attester text NOT NULL, attested_at timestamptz NOT NULL, signature text NOT NULL, payload_hash text NOT NULL, metadata jsonb NOT NULL);
